import{_ as a,o as t,c as i,a3 as s}from"./chunks/framework.CE6HLQbJ.js";const k=JSON.parse('{"title":"Resolution scaling & TAA","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/preview/feat-multi-view-engine/rendering/resolution-taa.html"}],["meta",{"property":"og:title","content":"Resolution scaling & TAA | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/preview/feat-multi-view-engine/rendering/resolution-taa.html"}],["meta",{"name":"twitter:title","content":"Resolution scaling & TAA | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"rendering/resolution-taa.md","filePath":"rendering/resolution-taa.md"}'),n={name:"rendering/resolution-taa.md"};function r(l,e,o,h,p,d){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="resolution-scaling-taa" tabindex="-1">Resolution scaling &amp; TAA <a class="header-anchor" href="#resolution-scaling-taa" aria-label="Permalink to &quot;Resolution scaling &amp; TAA&quot;">​</a></h1><h2 id="resolution-scaling" tabindex="-1">Resolution scaling <a class="header-anchor" href="#resolution-scaling" aria-label="Permalink to &quot;Resolution scaling&quot;">​</a></h2><p>The ray marcher renders at <code>renderScale</code> × the canvas size (0.25–1, default 0.5): at 0.5 a 1920 × 1080 canvas casts 960 × 540 rays, a quarter of the pixels. A blit pass upscales bilinearly. While the camera moves the scale drops to 0.25 and returns when the view settles (<code>KilnEngine.interactionRenderScale</code>; 0 disables the drop).</p><p>Overlays (wireframe, axis) and their depth buffer stay at full resolution.</p><h2 id="jitter-and-accumulation" tabindex="-1">Jitter and accumulation <a class="header-anchor" href="#jitter-and-accumulation" aria-label="Permalink to &quot;Jitter and accumulation&quot;">​</a></h2><p>Fixed sample positions produce banding where surfaces align with sample planes. Kiln turns the banding into noise and then averages it away:</p><ul><li><p><strong>Jitter:</strong> each ray&#39;s first sample is offset by a random fraction of a step, seeded with the frame index. The offset is applied at the first loaded brick, and after skipped bricks the samples advance by whole steps, so the pattern stays consistent along the ray.</p><div class="language-wgsl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">wgsl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> jitterFrac </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rand</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rayToSeed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(rayDir) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> uniforms</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">frameIndex);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tSample </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> t </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> jitterFrac </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> brick</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stepSize;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // at the first valid brick</span></span></code></pre></div></li><li><p><strong>Accumulation:</strong> a compute pass averages each new frame into a history texture (ping-pong pair) with <code>weight = 1 / (frameCount + 1)</code>. After 64 frames the image counts as converged and rendering stops until something changes.</p></li></ul><p>Accumulation restarts when:</p><ul><li>the camera moves</li><li>a render setting changes (mode, transfer function, window, threshold, …)</li><li>streamed bricks are committed, debounced to 100 ms after the last commit and at most 250 ms after the first, so a burst of bricks restarts it once</li></ul>`,9)])])}const u=a(n,[["render",r]]);export{k as __pageData,u as default};
